import { ed25519 } from '@noble/curves/ed25519.js';
import { encodeCanonical } from '../../../src/v2/cbor.js';
import type { MintNote, Transaction } from '../../../src/v2/models.js';
import { authorizationChallenge, nullifier, v2Hash } from '../../../src/v2/identifiers.js';
import { validateTransaction, V2ValidationError } from '../../../src/v2/validator.js';

const bytes = (value: number, length = 32) => new Uint8Array(length).fill(value);
const secret = bytes(41); const publicKey = ed25519.getPublicKey(secret); const domain = bytes(3); const asset = bytes(4); const opaque = new Uint8Array([1]);
const makeNote = (): MintNote => ({ kind: 'mint', asset_id: asset, amount: 10, recipient_key: publicKey, spend_domain: domain, output_commitment: bytes(6), output_id: bytes(7), issued_at: 1, expires_at: 100, mint_transaction_id: bytes(8), output_index: 0, keyset_id: bytes(9), mint_credential: { kind: 'mint', keyset_id: bytes(9), credential_payload: { keyset_id: bytes(9), asset_id: asset, spend_domain: domain, denomination: 10, issuance_epoch: 0, expiry_epoch: 1, blinded_payload: { owner_material: publicKey, replay_nonce: bytes(10) } }, signature_envelope: opaque } });
const makeTransaction = (): Transaction => ({ spend_domain: domain, inputs: [{ note: makeNote(), nullifier: nullifier(domain, bytes(7)), authorization_ref: 0 }], outputs: [{ asset_id: asset, amount: 10, recipient_key: bytes(11), spend_domain: domain, output_commitment: bytes(12), provenance: { kind: 'transition' } }], authorizations: [{ input_index: 0, owner_key_id: new Uint8Array(32), challenge: new Uint8Array(32), signature: new Uint8Array(64) }] });
const sign = (tx: Transaction) => { const auth = tx.authorizations[0]; const input = tx.inputs[0]; auth.owner_key_id = v2Hash('owner-key', (input.note as MintNote).recipient_key); const digest = v2Hash('transaction', encodeCanonical({ spend_domain: tx.spend_domain, inputs: tx.inputs.map((item) => ({ output_id: item.note.output_id, nullifier: item.nullifier, owner_key_id: v2Hash('owner-key', (item.note as MintNote).recipient_key) })), outputs: tx.outputs })); auth.challenge = authorizationChallenge(digest, auth.input_index, tx.spend_domain, auth.owner_key_id); auth.signature = ed25519.sign(auth.challenge, secret); };
const valid = makeTransaction(); sign(valid); validateTransaction(valid);
const expectReject = (mutate: (tx: Transaction) => void, category: string) => { const tx = makeTransaction(); sign(tx); mutate(tx); try { validateTransaction(tx); throw new Error('accepted invalid owner authorization'); } catch (error) { if (!(error instanceof V2ValidationError) || error.category !== category) throw error; } };
expectReject((tx) => { tx.authorizations[0].signature[0] ^= 1; }, 'authorization');
expectReject((tx) => { tx.authorizations[0].challenge[0] ^= 1; }, 'authorization');
expectReject((tx) => { tx.authorizations[0].owner_key_id = bytes(99); }, 'authorization');
expectReject((tx) => { tx.authorizations[0].input_index = 1; }, 'authorization');
expectReject((tx) => { tx.spend_domain = bytes(88); }, 'schema');
expectReject((tx) => { tx.authorizations[0].owner_key_id = bytes(1, 31); }, 'schema');
expectReject((tx) => { tx.authorizations[0].signature = new Uint8Array(63); }, 'schema');
expectReject((tx) => { tx.authorizations = []; }, 'authorization');
expectReject((tx) => { tx.authorizations.push({ ...tx.authorizations[0] }); }, 'authorization');
console.log('V2 owner-authorization tests: passed');
